<script setup>import{ref,onMounted}from'vue';import{ElMessage}from'element-plus';import{api}from'../api';const list=ref([]),keyword=ref(''),roleDialog=ref(false),current=ref();const load=async()=>list.value=await api.members(keyword.value);onMounted(load);function grant(row){current.value={memberId:row.id,staffRole:row.staffRole};roleDialog.value=true}async function save(){await api.grant(current.value);ElMessage.success('权限已更新，旧登录态将按新角色校验');roleDialog.value=false;load()}</script>
<template><div class="page-head"><div><h2>会员管理</h2><p>查看会员身份并授权现场工作人员</p></div></div><div class="panel"><div class="toolbar"><el-input v-model="keyword" placeholder="手机号或昵称" clearable style="width:260px" @keyup.enter="load"/><el-button @click="load">查询</el-button></div><el-table :data="list"><el-table-column prop="id" label="ID" width="80"/><el-table-column prop="nickname" label="昵称"/><el-table-column prop="phone" label="手机号"/><el-table-column label="现场角色"><template #default="{row}"><el-tag :type="row.staffRole==='admin'?'danger':row.staffRole==='verifier'?'warning':'info'">{{{customer:'顾客',verifier:'核销员',admin:'小程序管理员'}[row.staffRole]}}</el-tag></template></el-table-column><el-table-column prop="points" label="积分(预留)"/><el-table-column prop="createdAt" label="注册时间" min-width="180"/><el-table-column label="操作" width="110"><template #default="{row}"><el-button link type="primary" @click="grant(row)">角色授权</el-button></template></el-table-column></el-table></div><el-dialog v-model="roleDialog" title="设置小程序角色" width="420px"><el-radio-group v-if="current" v-model="current.staffRole"><el-radio-button value="customer">顾客</el-radio-button><el-radio-button value="verifier">核销员</el-radio-button><el-radio-button value="admin">管理员</el-radio-button></el-radio-group><template #footer><el-button @click="roleDialog=false">取消</el-button><el-button type="primary" @click="save">确认授权</el-button></template></el-dialog></template>
